function SiteIcon({name,className=''}){const paths={heart:'M12 21s-8-4.7-8-11a4.5 4.5 0 0 1 8-2.9A4.5 4.5 0 0 1 20 10c0 6.3-8 11-8 11Z',sparkle:'M12 2l2.2 7.8L22 12l-7.8 2.2L12 22l-2.2-7.8L2 12l7.8-2.2L12 2Z',moon:'M20.5 15.5A8.5 8.5 0 0 1 8.5 3.5 8.5 8.5 0 1 0 20.5 15.5Z',volume:'M4 10v4h4l5 4V6l-5 4H4Zm12.5-2.5a6 6 0 0 1 0 9m2.5-11.5a9.5 9.5 0 0 1 0 14',check:'m5 12 4 4L19 6'};return <svg className={`site-icon site-icon-${name} ${className}`} viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d={paths[name]||paths.sparkle}/></svg>}
function LayoutPreview({layout}){return <div className={`layout-demo layout-${layout.id}`}>{Array.from({length:layout.count},(_,i)=><i key={i} className="layout-demo-photo">{layout.id==='polaroid'&&<SiteIcon name="heart" className="layout-heart-icon"/>}</i>)}</div>}
function DesignPreview({design}){return design.template?<span className="design-template-preview"><img src={design.template.src} alt=""/></span>:<span className={'design-option-preview design-'+design.id} style={{'--frame-color':design.frame,'--frame-width':`${design.border*100}%`}}><i/><i/><i/></span>}
