function StickerLayer({stickers,selectedSticker,onStickerDown,onStickerMove,onStickerUp,onStickerSelect,onStickerRemove}){return <div className="composition-sticker-layer">{stickers.map(item=><div key={item.id} className={'composition-sticker '+(selectedSticker===item.id?'is-selected':'')} style={{left:`${item.x}%`,top:`${item.y}%`,width:`${item.size}%`,transform:`translate(-50%,-50%) rotate(${item.rotation}deg)`}} onPointerDown={e=>onStickerDown(e,item.id)} onPointerMove={e=>onStickerMove(e,item.id)} onPointerUp={onStickerUp} onClick={()=>onStickerSelect(item.id)}><img src={item.src} alt={item.name} draggable="false"/>{selectedSticker===item.id&&<><button type="button" className="sticker-remove-handle" aria-label={`Remove ${item.name}`} onPointerDown={e=>e.stopPropagation()} onClick={e=>{e.stopPropagation();onStickerRemove(item.id)}}>×</button><button type="button" className="sticker-resize-handle" aria-label={`Resize ${item.name}`} title="Drag to resize" onPointerDown={e=>onStickerDown(e,item.id,'resize')} onPointerMove={e=>onStickerMove(e,item.id)} onPointerUp={onStickerUp} onClick={e=>{e.stopPropagation();onStickerSelect(item.id)}}>↘</button></>}</div>)}</div>}
function TemplateComposition({design,photos,filter,stickers,selectedSticker,onStickerDown,onStickerMove,onStickerUp,onStickerSelect,onStickerRemove}){const template=design.template,groups=distributePhotos(photos,template.slots.length);return <div className={`strip-preview same-page-composition template-composition design-${design.id}`}><svg className="template-clip-defs" aria-hidden="true">{template.slots.map((slot,i)=>slot[4]==='heart'&&<clipPath key={i} id={`clip-${design.id}-${i}`} clipPathUnits="objectBoundingBox"><path d={HEART_CLIP_PATH}/></clipPath>)}</svg>{template.slots.map((slot,i)=><div className={`template-photo-slot shape-${slot[4]}`} key={i} style={{left:`${slot[0]/560*100}%`,top:`${slot[1]/1510*100}%`,width:`${slot[2]/560*100}%`,height:`${slot[3]/1510*100}%`,clipPath:slot[4]==='heart'?`url(#clip-${design.id}-${i})`:undefined}}>{groups[i]?.map((photo,j)=><img key={j} src={photo} alt={`Photo ${j+1}`} style={{left:`${j/groups[i].length*100}%`,width:`${100/groups[i].length}%`,filter}}/>)}</div>)}<img className="template-art" src={template.src} alt=""/><StickerLayer stickers={stickers} selectedSticker={selectedSticker} onStickerDown={onStickerDown} onStickerMove={onStickerMove} onStickerUp={onStickerUp} onStickerSelect={onStickerSelect} onStickerRemove={onStickerRemove}/></div>}
function StripComposition({layout,design,photos,filter,title,caption,stripColor,stripInk,stickers,selectedSticker,onStickerDown,onStickerMove,onStickerUp,onStickerSelect,onStickerRemove}){const stickerProps={stickers,selectedSticker,onStickerDown,onStickerMove,onStickerUp,onStickerSelect,onStickerRemove};if(design.template)return <TemplateComposition design={design} photos={photos} filter={filter} {...stickerProps}/>;return <div className={`strip-preview same-page-composition layout-${layout.id} design-${design.id}`} style={{'--paper':stripColor,'--ink':stripInk,'--accent':'#c67f91','--frame-color':design.frame,'--frame-width':`${design.border*100}%`}}><div className="preview-heading">{title||'little archive'}</div><div className="layout-photo-grid preview-photos" style={{gridTemplateColumns:`repeat(${layout.columns},minmax(0,1fr))`}}>{photos.map((p,i)=><div className={'preview-shot '+(layout.id==='polaroid'?'polaroid-shot':'')} style={layout.id==='polaroid'?{}:{aspectRatio:layout.ratio}} key={i}><img src={p} style={{filter}}/>{layout.id==='polaroid'&&<small>{caption||'a little moment'}</small>}</div>)}</div>{layout.id!=='polaroid'&&<p className="preview-caption">{caption||'a little moment'}</p>}<small className="preview-date">{new Date().toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}</small><StickerLayer {...stickerProps}/></div>}
function readableInk(hex){const n=parseInt((hex||'#f4dfe3').slice(1),16);const r=n>>16,g=(n>>8)&255,b=n&255;return (r*.299+g*.587+b*.114)>155?'#70564f':'#fffaf7';}
function loadImage(src){return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error(`Could not load ${src}`));image.src=src;});}
function clipTemplateSlot(ctx,slot){const [x,y,w,h,shape]=slot;ctx.beginPath();if(shape==='ellipse')ctx.ellipse(x+w/2,y+h/2,w/2,h/2,0,0,Math.PI*2);else if(shape==='heart'){ctx.moveTo(x+w*.5,y+h*.95);ctx.bezierCurveTo(x+w*.42,y+h*.85,x+w*.04,y+h*.61,x+w*.04,y+h*.35);ctx.bezierCurveTo(x+w*.04,y+h*.18,x+w*.22,y+h*.08,x+w*.36,y+h*.08);ctx.bezierCurveTo(x+w*.43,y+h*.08,x+w*.48,y+h*.13,x+w*.5,y+h*.2);ctx.bezierCurveTo(x+w*.52,y+h*.13,x+w*.57,y+h*.08,x+w*.64,y+h*.08);ctx.bezierCurveTo(x+w*.78,y+h*.08,x+w*.96,y+h*.18,x+w*.96,y+h*.35);ctx.bezierCurveTo(x+w*.96,y+h*.61,x+w*.58,y+h*.85,x+w*.5,y+h*.95);ctx.closePath();}else if(shape==='round'&&ctx.roundRect)ctx.roundRect(x,y,w,h,12);else ctx.rect(x,y,w,h);ctx.clip();}
function drawCroppedPhoto(ctx,image,x,y,w,h){const scale=Math.max(w/image.width,h/image.height),dw=image.width*scale,dh=image.height*scale;ctx.drawImage(image,x+(w-dw)/2,y+(h-dh)/2,dw,dh);}
function distributePhotos(photos,slotCount){if(!photos.length||!slotCount)return Array.from({length:slotCount},()=>[]);if(photos.length<slotCount)return Array.from({length:slotCount},(_,i)=>[photos[Math.floor(i*photos.length/slotCount)]]);return Array.from({length:slotCount},(_,i)=>photos.slice(Math.floor(i*photos.length/slotCount),Math.floor((i+1)*photos.length/slotCount)));}
function drawPhotoGroup(ctx,images,slot,filterCss='none'){if(!images.length)return;const [x,y,w,h]=slot,cellW=w/images.length;images.forEach((image,i)=>{ctx.save();ctx.filter=filterCss;drawCroppedPhoto(ctx,image,x+i*cellW,y,cellW,h);ctx.restore();});}
async function renderTemplateCanvas(ctx,template,photos,stickerItems,width,height,filterCss='none'){const scaleX=width/560,scaleY=height/1510;ctx.clearRect(0,0,width,height);ctx.save();ctx.scale(scaleX,scaleY);const photoImages=await Promise.all(photos.map(loadImage)),groups=distributePhotos(photoImages,template.slots.length);template.slots.forEach((slot,i)=>{if(!groups[i]?.length)return;ctx.save();clipTemplateSlot(ctx,slot);drawPhotoGroup(ctx,groups[i],slot,filterCss);ctx.restore();});ctx.drawImage(await loadImage(template.src),0,0,560,1510);const stickerImages=await Promise.all(stickerItems.map(async item=>({item,image:await loadImage(item.src)})));stickerImages.forEach(({item,image})=>{const size=(item.size/100)*560;ctx.save();ctx.translate((item.x/100)*560,(item.y/100)*1510);ctx.rotate(item.rotation*Math.PI/180);ctx.drawImage(image,-size/2,-(size*image.height/image.width)/2,size,size*image.height/image.width);ctx.restore();});ctx.restore();}

