  const [photos,setPhotos]=useState([]), [filter,setFilter]=useState('none'), [photoFilter,setPhotoFilter]=useState('none'), [caption,setCaption]=useState('a day to remember'), [title,setTitle]=useState('little archive'), [stripColor,setStripColor]=useState('#f4dfe3'), [colorHex,setColorHex]=useState('#f4dfe3'), [stickerItems,setStickerItems]=useState([]), [selectedSticker,setSelectedSticker]=useState(null);
  const [arFilter,setArFilter]=useState('none'), [arTracking,setArTracking]=useState('idle'), [cameraReady,setCameraReady]=useState(false);
  const [cameraError,setCameraError]=useState(()=>page==='booth'?'Your booth is back. Reconnect your camera to continue.':''), [countdown,setCountdown]=useState(null), [capturing,setCapturing]=useState(false), [flash,setFlash]=useState(false), [notice,setNotice]=useState(''), [qrData,setQrData]=useState(''), [qrLink,setQrLink]=useState(''), [qrLoading,setQrLoading]=useState(false), [qrError,setQrError]=useState('');
  const videoRef=useRef(null), streamRef=useRef(null), canvasRef=useRef(null), arCanvasRef=useRef(null), stickerDragRef=useRef(null), filterRef=useRef('none'), audioContextRef=useRef(null); const theme=themes.find(t=>t.id===themeId)||themes[1]; const layout=layouts.find(l=>l.id===layoutId)||layouts[0]; const design=stripDesigns.find(d=>d.id===designId)||stripDesigns[0]; const filterObj=filters.find(f=>f.id===filter),photoFilterObj=filters.find(f=>f.id===photoFilter)||filters[0]; const stripInk=readableInk(stripColor),creativeReady=photos.length>=count&&!capturing;filterRef.current=filterObj.css;
