  function setPage(next){if(page!==next){try{sessionStorage.setItem('little-archive-scroll','0');}catch{}window.scrollTo({top:0,behavior:'instant'});}try{localStorage.setItem('little-archive-page',next);}catch{}setPageState(next);}
