  function playShutterSound(){if(!soundEnabled)return;try{const ctx=audioContext();if(!ctx)return;const now=ctx.currentTime,buffer=ctx.createBuffer(1,Math.ceil(ctx.sampleRate*.055),ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*(1-i/data.length);const source=ctx.createBufferSource(),filterNode=ctx.createBiquadFilter(),gain=ctx.createGain();source.buffer=buffer;filterNode.type='lowpass';filterNode.frequency.value=1800;gain.gain.setValueAtTime(.2,now);gain.gain.exponentialRampToValueAtTime(.001,now+.055);source.connect(filterNode);filterNode.connect(gain);gain.connect(ctx.destination);source.start(now);source.stop(now+.055);const click=ctx.createOscillator(),clickGain=ctx.createGain();click.type='square';click.frequency.setValueAtTime(1250,now);click.frequency.exponentialRampToValueAtTime(220,now+.028);clickGain.gain.setValueAtTime(.09,now);clickGain.gain.exponentialRampToValueAtTime(.001,now+.03);click.connect(clickGain);clickGain.connect(ctx.destination);click.start(now);click.stop(now+.03);}catch{}}
  async function startCamera(){setCameraError('');setCameraReady(false);setArTracking('idle');setPage('booth');await new Promise(r=>setTimeout(r,40));try{if(!window.isSecureContext&&location.hostname!=='localhost'&&location.hostname!=='127.0.0.1')throw new Error('insecure-origin');if(!navigator.mediaDevices?.getUserMedia)throw new Error('unavailable');const s=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});streamRef.current=s;if(videoRef.current){videoRef.current.srcObject=s;await videoRef.current.play();setCameraReady(true);}}catch(e){setCameraError(e.message==='insecure-origin'?'insecure-origin':e.name==='NotAllowedError'?'Camera permission was blocked. Allow camera access in your browser settings, then try again.':e.name==='NotFoundError'?'No camera was found. Connect a camera and try again.':e.message==='unavailable'?'Camera access needs a secure browser window. Open this site on localhost or HTTPS.':'The camera could not start. Please try again.');}}
