  function addSticker(sticker){const id=`sticker-${Date.now()}-${Math.random().toString(16).slice(2)}`;setStickerItems(items=>[...items,{...sticker,id,x:76,y:48,size:18,rotation:(Math.random()*16)-8}]);setSelectedSticker(id);}
