  function finishStickerMove(){stickerDragRef.current=null;}
  function takeFrame(){const v=videoRef.current;if(!v||!v.videoWidth)return null;return captureFaceFilterFrame(v,(context,width,height)=>arCanvasRef.current?.drawTo(context,width,height),{width:v.videoWidth,height:v.videoHeight,mimeType:'image/png',quality:1,mirrorPreview:true,faceFilter:arFilter,colorFilter:filterRef.current});}
  async function runSession(){if(capturing)return;audioContext();setPhotos([]);setPhotoFilter('none');setStickerItems([]);setCapturing(true);for(let i=0;i<count;i++){for(let n=delay;n>0;n--){setCountdown(n);await new Promise(r=>setTimeout(r,900));}setCountdown('ready');setFlash(true);playShutterSound();await new Promise(r=>setTimeout(r,170));const frame=takeFrame();if(frame)setPhotos(p=>[...p,frame]);setFlash(false);setCountdown(null);await new Promise(r=>setTimeout(r,450));}setCapturing(false);stopCamera();}
  async function exportStrip(format='png'){if(!photos.length){setNotice('Take a few photos first.');return;}if(format==='gif'){await exportGif();return;}if(design.template){await exportTemplate(format);return;}try{const c=canvasRef.current,ctx=c.getContext('2d'),w=layout.width,pad=48,gap=20,head=82,foot=caption?112:74,columns=layout.columns,rows=Math.ceil(photos.length/columns),areaW=w-pad*2,photoW=(areaW-gap*(columns-1))/columns,photoH=layout.id==='polaroid'?photoW:photoW/layout.ratio,cellH=layout.id==='polaroid'?photoW*1.15:photoH;c.width=w;c.height=pad+head+rows*cellH+gap*(rows-1)+foot+pad;
    ctx.fillStyle=stripColor;ctx.fillRect(0,0,w,c.height);ctx.textAlign='center';ctx.fillStyle=stripInk;ctx.font='600 27px Georgia';ctx.fillText(title||'little archive',w/2,pad+35);
    const images=await Promise.all(photos.map(src=>new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=src;})));
    images.forEach((img,i)=>{const row=Math.floor(i/columns),col=i%columns,x=pad+col*(photoW+gap),y=pad+head+row*(cellH+gap),border=Math.max(8,Math.round(photoW*design.border)),imageW=photoW-2*border,imageH=photoH-2*border;ctx.fillStyle=design.frame;ctx.fillRect(x,y,photoW,cellH);if(design.id==='coquette'){ctx.save();ctx.strokeStyle='#d79eaa';ctx.lineWidth=2;ctx.setLineDash([5,5]);ctx.strokeRect(x+3,y+3,photoW-6,cellH-6);ctx.restore();}ctx.save();ctx.beginPath();ctx.rect(x+border,y+border,imageW,imageH);ctx.clip();const s=Math.max(imageW/img.width,imageH/img.height),dw=img.width*s,dh=img.height*s;ctx.filter=photoFilterObj.css;ctx.drawImage(img,x+border+(imageW-dw)/2,y+border+(imageH-dh)/2,dw,dh);ctx.restore();if(layout.id==='polaroid'){ctx.fillStyle=stripInk;ctx.textAlign='left';ctx.font='italic 18px Georgia';ctx.fillText(caption||'a little moment',x+border+8,y+photoH+(cellH-photoH)*.68);}});
    const stickerImages=await Promise.all(stickerItems.map(item=>new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve({img,item});img.onerror=reject;img.src=item.src;})));stickerImages.forEach(({img,item})=>{const size=(item.size/100)*w;ctx.save();ctx.translate((item.x/100)*w,(item.y/100)*c.height);ctx.rotate(item.rotation*Math.PI/180);ctx.drawImage(img,-size/2,-(size*img.height/img.width)/2,size,size*img.height/img.width);ctx.restore();});
    if(layout.id!=='polaroid'){ctx.fillStyle=theme.accent;ctx.textAlign='center';ctx.font='italic 27px Georgia';ctx.fillText(caption||'a little moment',w/2,c.height-pad-34);}ctx.font='13px Arial';ctx.fillStyle=stripInk;ctx.textAlign='center';ctx.fillText(new Date().toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'}),w/2,c.height-pad-12);if(format==='qr'){await createShareQr(c);return;}const mime=format==='jpeg'?'image/jpeg':'image/png',blob=await new Promise(resolve=>c.toBlob(resolve,mime,.94));if(!blob)throw new Error('The image could not be prepared. Please try again.');saveBlob(blob,`little-archive-${layout.id}.${format==='jpeg'?'jpg':'png'}`);setNotice(`your ${format.toUpperCase()} is ready`);setTimeout(()=>setNotice(''),2600);
    }catch(error){setNotice(error.message||'The download could not be created. Please try again.');setTimeout(()=>setNotice(''),4000);}
  }
  function saveBlob(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
