  async function exportTemplate(format){try{const c=canvasRef.current;c.width=560;c.height=1510;await renderTemplateCanvas(c.getContext('2d'),design.template,photos,stickerItems,560,1510,photoFilterObj.css);if(format==='qr'){await createShareQr(c);return;}const mime=format==='jpeg'?'image/jpeg':'image/png',blob=await new Promise(resolve=>c.toBlob(resolve,mime,.94));if(!blob)throw new Error('The image could not be prepared. Please try again.');saveBlob(blob,`little-archive-${design.id}.${format==='jpeg'?'jpg':'png'}`);setNotice(`your ${format.toUpperCase()} is ready`);setTimeout(()=>setNotice(''),2600);}catch(error){setNotice(error.message||'The download could not be created. Please try again.');setTimeout(()=>setNotice(''),4000);}}
  async function exportTemplateGif(){try{const width=360,height=Math.round(1510*360/560),art=await loadImage(design.template.src),photoImages=await Promise.all(photos.map(loadImage)),stickerImages=await Promise.all(stickerItems.map(async item=>({item,image:await loadImage(item.src)}))),frames=[];for(let step=0;step<photos.length;step++){const frame=document.createElement('canvas');frame.width=width;frame.height=height;const ctx=frame.getContext('2d'),ordered=photoImages.map((_,i)=>photoImages[(i+step)%photoImages.length]),groups=distributePhotos(ordered,design.template.slots.length);ctx.clearRect(0,0,width,height);ctx.save();ctx.scale(width/560,height/1510);design.template.slots.forEach((slot,i)=>{if(!groups[i]?.length)return;ctx.save();clipTemplateSlot(ctx,slot);drawPhotoGroup(ctx,groups[i],slot,photoFilterObj.css);ctx.restore();});ctx.drawImage(art,0,0,560,1510);stickerImages.forEach(({item,image})=>{const size=item.size/100*560;ctx.save();ctx.translate(item.x/100*560,item.y/100*1510);ctx.rotate(item.rotation*Math.PI/180);ctx.drawImage(image,-size/2,-(size*image.height/image.width)/2,size,size*image.height/image.width);ctx.restore();});ctx.restore();frames.push(ctx.getImageData(0,0,width,height).data);}const all=new Uint8Array(frames.reduce((n,frame)=>n+frame.length,0));let offset=0;frames.forEach(frame=>{all.set(frame,offset);offset+=frame.length;});const palette=quantize(all,256),gif=GIFEncoder();frames.forEach((rgba,i)=>gif.writeFrame(applyPalette(rgba,palette),width,height,{palette,delay:650,repeat:i===0?0:undefined,dispose:2}));gif.finish();saveBlob(new Blob([gif.bytes()],{type:'image/gif'}),`little-archive-${design.id}.gif`);setNotice('your animated GIF is ready');setTimeout(()=>setNotice(''),2600);}catch(error){setNotice(error.message||'The GIF could not be created. Please try again.');setTimeout(()=>setNotice(''),4000);}}
  async function exportGif(){if(photos.length<2){setNotice('Animated GIF needs at least two photos.');return;}if(design.template){await exportTemplateGif();return;}try{const width=360,height=480,frames=[],stickerImages=await Promise.all(stickerItems.map(item=>new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve({image,item});image.onerror=reject;image.src=item.src;})));for(let i=0;i<photos.length;i++){const img=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=reject;image.src=photos[i];}),frame=document.createElement('canvas');frame.width=width;frame.height=height;const ctx=frame.getContext('2d');ctx.fillStyle=stripColor;ctx.fillRect(0,0,width,height);ctx.fillStyle=stripInk;ctx.textAlign='center';ctx.font='600 20px Georgia';ctx.fillText(title||'little archive',width/2,34);ctx.fillStyle=theme.accent;ctx.font='10px Arial';ctx.fillText(`${i+1} / ${photos.length}`,width/2,52);const x=28,y=72,frameW=width-56,frameH=316,border=Math.max(7,Math.round(frameW*design.border));ctx.fillStyle=design.frame;ctx.fillRect(x,y,frameW,frameH);if(design.id==='coquette'){ctx.strokeStyle='#d79eaa';ctx.lineWidth=2;ctx.setLineDash([5,5]);ctx.strokeRect(x+3,y+3,frameW-6,frameH-6);ctx.setLineDash([]);}const ix=x+border,iy=y+border,iw=frameW-border*2,ih=frameH-border*2,scale=Math.min(iw/img.width,ih/img.height),dw=img.width*scale,dh=img.height*scale;ctx.filter=photoFilterObj.css;ctx.drawImage(img,ix+(iw-dw)/2,iy+(ih-dh)/2,dw,dh);ctx.filter='none';ctx.fillStyle=theme.accent;ctx.font='italic 18px Georgia';ctx.fillText(caption||'a little moment',width/2,420);ctx.fillStyle=stripInk;ctx.font='10px Arial';ctx.fillText(new Date().toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'}),width/2,448);stickerImages.forEach(({image,item})=>{const size=(item.size/100)*width;ctx.save();ctx.translate((item.x/100)*width,(item.y/100)*height);ctx.rotate(item.rotation*Math.PI/180);ctx.drawImage(image,-size/2,-(size*image.height/image.width)/2,size,size*image.height/image.width);ctx.restore();});frames.push(ctx.getImageData(0,0,width,height).data);}const all=new Uint8Array(frames.reduce((n,frame)=>n+frame.length,0));let offset=0;frames.forEach(frame=>{all.set(frame,offset);offset+=frame.length;});const palette=quantize(all,256),gif=GIFEncoder();frames.forEach((rgba,i)=>gif.writeFrame(applyPalette(rgba,palette),width,height,{palette,delay:650,repeat:i===0?0:undefined,dispose:2}));gif.finish();saveBlob(new Blob([gif.bytes()],{type:'image/gif'}),`little-archive-${layout.id}.gif`);setNotice('your animated GIF is ready');setTimeout(()=>setNotice(''),2600);}catch(error){setNotice(error.message||'The GIF could not be created. Please try again.');setTimeout(()=>setNotice(''),4000);}}
